@[c: 'GC_thread_is_registered']
fn C.c2v_GC_thread_is_registered() i32

@[c: 'GC_allow_register_threads']
fn C.c2v_GC_allow_register_threads()

@[c: 'pthread_key_create']
fn C.c2v_pthread_key_create(voidptr, voidptr) i32

@[c: 'pthread_setspecific']
fn C.c2v_pthread_setspecific(usize, voidptr) i32

__global c2v_gc_thread_key = u64(0)

pub fn c2v_gc_thread_exit(value voidptr) {
	$if gcboehm ? {
		C.GC_unregister_my_thread()
	}
}

pub fn c2v_gc_register_thread() {
	$if gcboehm ? {
		if C.c2v_GC_thread_is_registered() != 0 {
			return
		}
		mut base := [4]voidptr{}
		if C.GC_get_stack_base(unsafe { voidptr(&base[0]) }) != 0 {
			return
		}
		C.GC_register_my_thread(unsafe { voidptr(&base[0]) })
		$if !windows {
			if c2v_gc_thread_key == 0 {
				C.c2v_pthread_key_create(voidptr(&c2v_gc_thread_key), voidptr(c2v_gc_thread_exit))
			}
			C.c2v_pthread_setspecific(usize(c2v_gc_thread_key), voidptr(1))
		}
	}
}

pub fn c2v_gc_allow_threads() {
	$if gcboehm ? {
		C.c2v_GC_allow_register_threads()
	}
}

fn init() {
	c2v_gc_allow_threads()
}

pub fn c2v_alloca(mut blocks []voidptr, size usize) voidptr {
	memory := unsafe { C.c2v_malloc(if size == 0 { usize(1) } else { size }) }
	blocks << memory
	return memory
}

pub fn c2v_alloca_free(blocks []voidptr) {
	for block in blocks {
		unsafe { C.c2v_free(block) }
	}
}

pub fn c2v_builtin_bswap16(value u16) u16 {
	return (value >> 8) | (value << 8)
}

pub fn c2v_builtin_bswap32(value u32) u32 {
	return (value >> 24) | ((value >> 8) & u32(0x0000ff00)) | ((value << 8) & u32(0x00ff0000)) | (value << 24)
}

pub fn c2v_builtin_trap() {
	panic('C __builtin_trap')
}

pub fn c2v_pointer_postfix[T](storage voidptr, pointer &T, delta isize) &T {
	unsafe { *(&&T(storage)) = pointer + delta }
	old := pointer
	return old
}

pub fn c2v_pointer_prefix[T](storage voidptr, pointer &T, delta isize) &T {
	updated := unsafe { pointer + delta }
	unsafe { *(&&T(storage)) = updated }
	return updated
}

